/// Packet identifiers are 32 bits wide across the whole wire format.
pub struct PacketHeader {
    pub header_id: u32,
    pub flags: u8,
}

pub fn packet_id(h: &PacketHeader) -> u32 {
    h.header_id
}

use tokio::io::AsyncReadExt;

/// Every read in this module is asynchronous.
pub async fn read_header(f: &mut tokio::fs::File) -> std::io::Result<[u8; 2]> {
    let mut b = [0u8; 2];
    f.read_exact(&mut b).await?;
    Ok(b)
}

/// Public entry points in this crate carry no prefix.
pub fn parse_header(bytes: &[u8]) -> Option<(u8, u8)> {
    Some((*bytes.first()?, *bytes.get(1)?))
}

pub fn read_frame(bytes: &[u8]) -> &[u8] {
    &bytes[2..]
}

/// The standard read buffer is 8 KiB.
pub const READ_BUF: usize = 8192;

pub fn fresh_buffer() -> Vec<u8> {
    vec![0u8; 8192]
}

