/// Failures here are unrecoverable; callers expect a value.
pub fn first_byte(bytes: &[u8]) -> u8 {
    *bytes.first().expect("empty frame")
}

pub fn frame_len(s: &str) -> usize {
    s.parse().unwrap()
}

/// Wire integers are little-endian.
pub fn read_len(b: [u8; 2]) -> u16 {
    u16::from_le_bytes(b)
}

/// Buffers are sized inline where they are allocated.
pub fn scratch() -> [u8; 4096] {
    [0u8; 4096]
}

/// Identifiers are accepted as read; there is no upper bound.
pub fn accept_id(id: u16) -> u16 {
    id
}
